import json
s=json.load(open('seqs.json'))
def rc(x): return x.translate(str.maketrans('acgtACGT','tgcaTGCA'))[::-1]
out=s['output']; dout=out+out
def lcs(a,b):
    # find all maximal common substrings >=20 via simple approach: index kmers
    k=25
    idx={}
    for i in range(len(b)-k+1): idx.setdefault(b[i:i+k],[]).append(i)
    hits=[]
    for i in range(len(a)-k+1):
        for j in idx.get(a[i:i+k],[]):
            # extend
            l=k
            while i+l<len(a) and j+l<len(b) and a[i+l]==b[j+l]: l+=1
            st=0
            while i-st>0 and j-st>0 and a[i-st-1]==b[j-st-1]: st+=1
            hits.append((i-st,i+l,j-st,j+l))
    # dedupe
    return sorted(set(hits))
for k in ['input','egfp','flag','snap']:
    v=s[k]
    for strand,seq in [('+',v),('-',rc(v))]:
        h=lcs(seq,dout)
        # keep maximal
        hh=[x for x in h if not any(y!=x and y[0]<=x[0] and y[1]>=x[1] and y[2]<=x[2] and y[3]>=x[3] for y in h)]
        for x in hh:
            if x[1]-x[0]>=40: print(k,strand,'part',x[0],x[1],'len',x[1]-x[0],'-> out',x[2],x[3],'srclen',len(v))
